// === ESTRUCTURA DEL PATRÓN SINGLETON ===

// Clásico — constructor privado + getInstance()
class Logger {
  private static instance: Logger;
  private logs: string[] = [];

  // Constructor privado — nadie puede hacer new Logger()
  private constructor() {
    console.log('Logger inicializado');
  }

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger();
    }
    return Logger.instance;
  }

  log(message: string) {
    const entry = `[${new Date().toISOString()}] ${message}`;
    this.logs.push(entry);
    console.log(entry);
  }

  getLogs(): string[] {
    return [...this.logs];
  }
}

// Uso:
const logger1 = Logger.getInstance();
const logger2 = Logger.getInstance();
console.log(logger1 === logger2); // true — misma instancia

logger1.log('App iniciada');
logger2.log('Request recibido');
console.log(logger1.getLogs()); // ['App iniciada', 'Request recibido']

// new Logger(); // Error: constructor is private

// --- Alternativa moderna: Module Singleton ---
// logger.ts
let instance: Logger | null = null;

export function getLogger(): Logger {
  if (!instance) {
    instance = new Logger();
  }
  return instance;
}

