// Singleton — siempre la misma instancia
class Logger {
  private static instance: Logger;
  private logs: string[] = [];

  private constructor() {}

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger();
    }
    return Logger.instance;
  }

  log(message: string) {
    this.logs.push(message);
    console.log(message);
  }
}

// Todos los módulos comparten la misma instancia
const logger = Logger.getInstance();
logger.log('Init');    // Guardado centralizado
logger.log('Request'); // Mismo logger, mismo array de logs

