export class ConfigManager {
  private config: Record<string, string> = {};

  constructor() {
    // Simula carga de config (podría ser de .env o archivo)
    this.config = {
      DB_HOST: 'localhost',
      DB_PORT: '5432',
      API_KEY: 'secret-123',
    };
  }

  get(key: string): string | undefined {
    return this.config[key];
  }

  getAll(): Record<string, string> {
    return { ...this.config };
  }
}

